import{_ as r,C as i,o as l,c as d,a9 as s,E as a,j as t,a as n}from"./chunks/framework.asyjyako.js";const v=JSON.parse('{"title":"Plots, notebooks and Julia tools","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode-workflows.md","filePath":"interfaces/vscode-workflows.md","lastUpdated":null}'),c={name:"interfaces/vscode-workflows.md"};function h(p,e,u,g,f,m){const o=i("DocMedia");return l(),d("div",null,[e[0]||(e[0]=s('<h1 id="Plots,-notebooks-and-Julia-tools" tabindex="-1">Plots, notebooks and Julia tools <a class="header-anchor" href="#Plots,-notebooks-and-Julia-tools" aria-label="Permalink to &quot;Plots, notebooks and Julia tools {#Plots,-notebooks-and-Julia-tools}&quot;">​</a></h1><p>Use saved evidence in full VS Code tabs, and run exploratory Julia code in an explicit notebook, terminal or debugger session. Studio links these surfaces without starting them on opening.</p><h2 id="Plot-saved-results" tabindex="-1">Plot saved results <a class="header-anchor" href="#Plot-saved-results" aria-label="Permalink to &quot;Plot saved results {#Plot-saved-results}&quot;">​</a></h2><p>Select a completed suite run in PerfChecker, then choose <strong>PerfChecker: Open visual output</strong>. The extension reads the saved suite report and opens available plots in an editor panel. Keep it beside the workload or use editor groups to compare reports. Native TestItems retain their separate JSON evidence in the <strong>PerfChecker test items</strong> output channel.</p><p>In the visual output, select <strong>Version series</strong> to compare recorded targets. Use the package, feature and check filters to narrow the evidence. Hover a point or focus its accessible button to inspect the value and unit. <strong>JSON</strong> and <strong>Series JSON</strong> open the underlying saved data when you need its provenance.</p>',5)),a(o,{src:"/assets/screenshots/vscode-results.png",alt:"PerfChecker V1 output webview rendered in Chromium, displaying version filters, a normalized overlay and timing points with nanosecond units",caption:"Read units and raw values before comparing: the overlay sets each metric's minimum to 1, while the version series retains the recorded unit. These are demonstration results in the real extension UI, not measurements of a published package."}),e[1]||(e[1]=s('<p>The normalized overlay makes different metrics readable together; a ratio of two for bytes and a ratio of two for time do not describe the same quantity. Select the corresponding raw series and compatible collector before drawing a conclusion. The screenshot&#39;s version labels belong to the demonstration package, not to PerfChecker&#39;s release version.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Visual</th><th style="text-align:right;">Evidence needed</th><th style="text-align:right;">Interpretation</th></tr></thead><tbody><tr><td style="text-align:right;">Distribution</td><td style="text-align:right;">Timing/allocation samples</td><td style="text-align:right;">Spread, outliers and sample count for the recorded configuration</td></tr><tr><td style="text-align:right;">Allocation view</td><td style="text-align:right;">Allocation samples or sites</td><td style="text-align:right;">Allocation activity, with units and sampling limits</td></tr><tr><td style="text-align:right;">Flame graph</td><td style="text-align:right;">Recorded profile stacks</td><td style="text-align:right;">Sampled call-path weights; not independent timing observations</td></tr><tr><td style="text-align:right;">Version comparison</td><td style="text-align:right;">Compatible target observations</td><td style="text-align:right;">Differences against the selected baseline and aggregation policy</td></tr><tr><td style="text-align:right;">Overlay</td><td style="text-align:right;">Comparable saved series</td><td style="text-align:right;">Contrast recorded configurations without inventing missing samples</td></tr></tbody></table><p>A report without profile stacks cannot produce a measured flame graph. A missing configuration remains unmeasured. Open worker output or source from the same run if a result is incomplete.</p><h3 id="Read-a-distribution" tabindex="-1">Read a distribution <a class="header-anchor" href="#Read-a-distribution" aria-label="Permalink to &quot;Read a distribution {#Read-a-distribution}&quot;">​</a></h3><p>Open the <strong>Distributions</strong> view for a completed check. Keep its unit, sample count and collector beside the chart. A narrow distribution still describes only that recorded configuration; it does not establish a general property of the function.</p>',5)),a(o,{video:"",short:"",recording:"perfchecker-vscode-v101-short-15",src:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-15.mp4",poster:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-15-poster.jpg",subtitles:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-15-en.vtt",preload:"metadata",alt:"Actual PerfChecker saved distribution, allocation median of 48 bytes, raw series and source JSON in native VS Code",caption:"Inspect actual worker measurements in their own units. The 48 B median is read from the recorded Example hello report. Recorded build: VSIX 75f84f, Core 975d, VS Code 1.141 on Linux."}),e[2]||(e[2]=t("h3",{id:"Read-normalized-overlays",tabindex:"-1"},[n("Read normalized overlays "),t("a",{class:"header-anchor",href:"#Read-normalized-overlays","aria-label":'Permalink to "Read normalized overlays {#Read-normalized-overlays}"'},"​")],-1)),e[3]||(e[3]=t("p",null,"Each metric uses its own reference minimum. A ratio of one describes that metric's minimum; inspect the raw value and unit in the tooltip before drawing a conclusion. The example below preserves the actual saved version series.",-1)),a(o,{video:"",short:"",recording:"perfchecker-vscode-v101-short-04",src:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-04.mp4",poster:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-04-poster.jpg",subtitles:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-04-en.vtt",preload:"metadata",alt:"Actual native PerfChecker minimum-relative chart, raw units and recorded version tooltip",caption:"Read each metric against its own minimum, then inspect its raw value. The recorded tooltip is 136 ns with ratio 1.0149; units remain separate. Recorded build: VSIX 75f84f, Core 975d, VS Code 1.141 on Linux."}),e[4]||(e[4]=t("h3",{id:"Follow-a-recorded-profile",tabindex:"-1"},[n("Follow a recorded profile "),t("a",{class:"header-anchor",href:"#Follow-a-recorded-profile","aria-label":'Permalink to "Follow a recorded profile {#Follow-a-recorded-profile}"'},"​")],-1)),e[5]||(e[5]=t("p",null,[n("Select "),t("strong",null,"Flame graphs"),n(" for a check containing real profile stacks. Follow the frame names and source locations, then inspect the collector's sampling boundary. Use a profile to choose a workload and a correctness protocol for the next experiment.")],-1)),a(o,{video:"",short:"",recording:"perfchecker-vscode-v101-short-16",src:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-16.mp4",poster:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-16-poster.jpg",subtitles:"/assets/videos/vscode/v101/perfchecker-vscode-1.0.1-short-16-en.vtt",preload:"metadata",alt:"Actual native PerfChecker CPU flame graph with a closer view of sum_squares, materialize and copy",caption:"Follow real recorded profile stacks. The closer view preserves the original frame labels; profile weights describe the stated collector. Recorded build: VSIX 75f84f, Core 975d, VS Code 1.141 on Linux."}),e[6]||(e[6]=s('<p>These are passages from the full tutorial, with English captions and the original narration. The <a href="./vscode-videos">video walkthrough index</a> groups them by action.</p><p>For custom Julia figures, load <a href="./visualization">PerfCheckerMakie</a> with your chosen Makie backend. The core notebook&#39;s <code>display(bundle)</code> presents a bundle; it does not automatically create every optional graphical backend. Save reports or create figures explicitly when you need reusable plots.</p><h2 id="Notebook-versions" tabindex="-1">Notebook versions <a class="header-anchor" href="#Notebook-versions" aria-label="Permalink to &quot;Notebook versions {#Notebook-versions}&quot;">​</a></h2><p>The integrated Pluto workflow below is a <strong>1.0.1 candidate</strong>. Its native editor qualification and General installation check are still in progress. Public extension <strong>1.0.0</strong> uses the earlier notebook workflow described at the end of this section. Install the corrected releases before using the candidate steps.</p><h2 id="Pluto-notebooks-in-VS-Code" tabindex="-1">Pluto notebooks in VS Code <a class="header-anchor" href="#Pluto-notebooks-in-VS-Code" aria-label="Permalink to &quot;Pluto notebooks in VS Code {#Pluto-notebooks-in-VS-Code}&quot;">​</a></h2><p>The integrated Pluto workflow requires <strong>PerfChecker for VS Code 1.0.1 or newer</strong> and the corrected <strong>PerfChecker core 1.0.1 or newer</strong>. Both releases must be available before following this workflow. Use <strong>PerfChecker: New Pluto notebook</strong> to create a native <code>.jl</code> notebook, or <strong>PerfChecker: Open Pluto notebook</strong> to reopen one in an interactive editor tab. The extension starts a Julia-backed Pluto session and displays its actual notebook interface inside VS Code.</p><h3 id="Create-a-dashboard" tabindex="-1">Create a dashboard <a class="header-anchor" href="#Create-a-dashboard" aria-label="Permalink to &quot;Create a dashboard {#Create-a-dashboard}&quot;">​</a></h3><ol><li><p>Open the intended trusted package folder and check its suite or scenario configuration in Studio.</p></li><li><p>Choose <strong>New Pluto notebook</strong>, then save a new <code>.jl</code> file inside that folder. The suggested location is <code>perf/notebooks/performance.jl</code>.</p></li><li><p>Select <strong>Feature suite</strong> for suite checks and saved reports, or <strong>Investigation</strong> for discovery, scenarios, diagnosis and advice.</p></li><li><p>If the separate Pluto environment is missing or incompatible, review the installation prompt. <strong>Install Pluto environment</strong> downloads the listed packages into <code>perfchecker.plutoProject</code>, whose default is <code>perf/pluto</code>. Cancelling leaves the installation unrequested; opening Studio never installs those packages.</p></li><li><p>Wait for the notebook tab to become ready. In <strong>Feature suite</strong>, select the workload, collector and target, inspect the printed plan, then choose <strong>Launch selected checks</strong>.</p></li><li><p>Use <strong>Refresh status</strong> to inspect the job and <strong>Cancel active job</strong> to interrupt active work. After completion, refresh and choose <strong>Save completed reports</strong>, then open their visual output from PerfChecker.</p></li></ol><p>An <strong>Investigation</strong> notebook instead offers <strong>Launch selected action</strong>, <strong>Cancel active investigation</strong> and <strong>Refresh status and evidence</strong>. Review its chosen action and declared scenarios before launch. If no suite file exists, a feature notebook opens as a saved-report reader; create or configure the suite before expecting executable checks.</p>',9)),a(o,{src:"/assets/screenshots/vscode/v101/pluto-macos-intel.png",alt:"Native VS Code 1.141.0 on a macOS Intel CI host displaying the generated PerfChecker Pluto suite notebook, its package, workload, collector and target selectors, and Open source, Stop session and Restart session controls",caption:"Review the package, workload, collector and target selectors inside the VS Code editor tab. This capture records only an idle notebook opening in the 1.0.1 candidate, with a demonstration package."}),e[7]||(e[7]=s(`<p>This native capture uses VSIX candidate <code>75f84f631ba3</code>, Core candidate <code>6f6155510aa2</code> and Julia <strong>1.13.1</strong>. Its configured opening phase passed; the complete notebook lifecycle and final release qualification remain in progress. The image opens at full resolution when selected.</p><p>The integration uses the official notebook generators supplied by PerfChecker and its PerfCheckerPluto companion. The generated notebook is editable Julia source. Opening it or changing a selector does not request a new measurement. Pluto still executes reactive Julia cells: inspect an unfamiliar notebook before trusting and opening it.</p><p>For an investigation, <code>scenarioCatalog</code> selects the declared scenarios and <code>scenarioProject</code> selects their target environment. Prepare the measured package, scenario dependencies and requested analyzers there. The notebook&#39;s own environment contains the interface packages; it is separate from the target workers. A missing analyzer is unavailable rather than a passing diagnosis.</p><h3 id="Keep-the-Pluto-environment-separate" tabindex="-1">Keep the Pluto environment separate <a class="header-anchor" href="#Keep-the-Pluto-environment-separate" aria-label="Permalink to &quot;Keep the Pluto environment separate {#Keep-the-Pluto-environment-separate}&quot;">​</a></h3><p>The candidate integration targets Pluto <strong>1.0.4</strong>, the corrected PerfChecker core, PlutoUI, BenchmarkTools, Chairmarks and its official PerfCheckerPluto companion. Use the companion tag recorded by the qualified extension release. Set the folder configuration explicitly when you use several environments:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.runnerProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/controller&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.scenarioProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.plutoProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/pluto&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pluto 1.0.4&#39;s published dependency range uses HTTP 1.x, while the qualified MCP controller uses HTTP 2.x. A separate Pluto environment keeps these resolved dependencies independent. This is a constraint of the qualified Pluto release: later Pluto releases may support both ranges. Do not install this stable Pluto setup into the measurement/MCP controller; the guided installer refuses that overlap. See <a href="./../guide/installation">optional interface installation</a> if you prefer to prepare the environment manually.</p><h3 id="Edit,-save-and-reopen" tabindex="-1">Edit, save and reopen <a class="header-anchor" href="#Edit,-save-and-reopen" aria-label="Permalink to &quot;Edit, save and reopen {#Edit,-save-and-reopen}&quot;">​</a></h3><ol><li><p>Expand the source of a notebook cell and edit its Julia code. Submit the cell with <strong>Ctrl+Enter</strong> (<strong>Cmd+Enter</strong> on macOS) to update its reactive output.</p></li><li><p>Wait for Pluto to save the cell to the <code>.jl</code> file. These saved cell edits are separate from <strong>Save completed reports</strong>, which writes completed suite evidence.</p></li><li><p>Reopen the file with <strong>PerfChecker: Open Pluto notebook</strong>. An active notebook reuses its existing tab and server; a stopped session starts from the saved source. Changing selectors or reopening retains saved evidence without launching the checks again.</p></li></ol><h3 id="Manage-the-session-and-saved-source" tabindex="-1">Manage the session and saved source <a class="header-anchor" href="#Manage-the-session-and-saved-source" aria-label="Permalink to &quot;Manage the session and saved source {#Manage-the-session-and-saved-source}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Effect</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Open source</strong></td><td style="text-align:right;">Open the saved <code>.jl</code> notebook in the Julia source editor</td></tr><tr><td style="text-align:right;"><strong>Stop session</strong></td><td style="text-align:right;">Shut down this notebook&#39;s Julia/Pluto process; retain the saved notebook and reports</td></tr><tr><td style="text-align:right;"><strong>Restart session</strong></td><td style="text-align:right;">Stop the current process and start the saved notebook again</td></tr><tr><td style="text-align:right;"><strong>PerfChecker: Stop Pluto notebook sessions</strong></td><td style="text-align:right;">Stop the sessions belonging to the selected workspace folder</td></tr><tr><td style="text-align:right;">Pluto homepage session button</td><td style="text-align:right;">Confirm shutdown of that notebook and its owned jobs; the Pluto server remains available</td></tr></tbody></table><p>Pluto saves cell edits to the notebook file. Reopening the same active notebook reveals its existing tab; closing that tab stops its process. Removing its workspace folder also shuts down its session. Stop a session before editing its source externally, then restart to load the saved changes. Unsaved Julia editor buffers are separate from Pluto&#39;s own saved cells.</p><p>After shutting down a notebook from Pluto&#39;s homepage, use <strong>Restart session</strong> in the PerfChecker header to reopen its saved source. Stop and restart request cancellation of owned PerfChecker jobs and wait for their cleanup before closing the notebook worker. Wait for the final status and inspect diagnostics when a shutdown reports an error.</p><p>Core cleans its owned worker environments, allocation journals and <code>.mem</code> files separately. A workload&#39;s <code>cleanup(state)</code> callback runs during normal Julia unwinding; terminating its isolated process cannot guarantee that an arbitrary user callback runs. Keep files created by the workload recoverable, and inspect a forced-stop diagnostic before restarting.</p><p>Use <strong>View → Output → PerfChecker Pluto</strong> for setup, startup and session errors. The notebook server binds to loopback and the extension handles its session URL; do not share that URL or include it in a bug report. Remote workspace forwarding depends on VS Code&#39;s extension-host port support. Report an unavailable forwarded session with the editor, extension and Julia versions and redacted diagnostics. <a id="Investigation-notebooks"></a></p><h3 id="Public-extension-1.0.0-notebooks" tabindex="-1">Public extension 1.0.0 notebooks <a class="header-anchor" href="#Public-extension-1.0.0-notebooks" aria-label="Permalink to &quot;Public extension 1.0.0 notebooks {#Public-extension-1.0.0-notebooks}&quot;">​</a></h3><p>The earlier <strong>New investigation notebook</strong> and <strong>Open Julia notebook</strong> actions use <code>.ipynb</code> and require a Julia kernel provider. Existing notebooks remain separate from Pluto&#39;s <code>.jl</code> format; PerfChecker does not convert them. Retain their saved source and consult the <a href="https://perfchecker.mirageinteractive.fr/v1.0.0/interfaces/vscode-workflows.html#Investigation-notebooks" target="_blank" rel="noreferrer">archived 1.0.0 notebook instructions</a> when maintaining that workflow. For a new investigation with the corrected 1.0.1 releases, follow the Pluto steps above.</p><h2 id="Dedicated-Julia-terminal" tabindex="-1">Dedicated Julia terminal <a class="header-anchor" href="#Dedicated-Julia-terminal" aria-label="Permalink to &quot;Dedicated Julia terminal {#Dedicated-Julia-terminal}&quot;">​</a></h2><p><strong>PerfChecker: Open Julia terminal</strong> starts a terminal named <strong>PerfChecker · package-name</strong> with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --startup-file=no --project=&lt;resolved-controller-project&gt; -i</span></span></code></pre></div><p>Its working directory is the selected package. The executable comes from <code>perfchecker.juliaExecutable</code>. A compatible existing PerfChecker terminal is reused; changing the project/executable creates a separately configured session.</p><p>Use it to inspect the public API or deliberately rerun a check. Interactive terminal state is independent from fresh measurement workers. Use saved bundle provenance for reproducibility rather than assuming the terminal matches a previous run.</p><h2 id="Julia-debugging" tabindex="-1">Julia debugging <a class="header-anchor" href="#Julia-debugging" aria-label="Permalink to &quot;Julia debugging {#Julia-debugging}&quot;">​</a></h2><p>Install the Julia VS Code extension (<code>julialang.language-julia</code>) and open a saved Julia source file belonging to the selected package. Choose <strong>PerfChecker: Debug current Julia file</strong>. PerfChecker delegates to the Julia debug adapter, requests the selected scenario project in its launch configuration and stops on entry. Inspect the actual runtime project before relying on that environment.</p><div class="tip custom-block"><p class="custom-block-title">Qualified runtime and project selection</p><p>Native VS Code <strong>1.141.0</strong> on Linux and Windows, the Julia extension <strong>1.249.2</strong> and Julia <strong>1.12.7</strong> passed the REPL and debugger checks with the 1.0.1 extension build. Both debug sessions executed the target source, checked <code>VERSION</code>, <code>Base.active_project()</code> and the correctness oracle, and used the intended controller in two distinct workspace folders. PerfChecker&#39;s measurement runner used Julia <strong>1.13.1</strong> separately. This proof covers the selected target source; full PerfChecker startup under the debugger&#39;s interpreter was not exercised. Check the same runtime and project fields in your stopped session.</p></div><ol><li><p>Use deterministic advice to identify a workload or correctness failure.</p></li><li><p>Open its source and set a breakpoint.</p></li><li><p>Debug the file and inspect state, inputs and the oracle.</p></li><li><p>Finish debugging; rerun isolated correctness and performance checks.</p></li><li><p>Compare saved compatible results before adopting a change.</p></li></ol><p>Debugger overhead and stepping change execution. Use debugging for correctness investigation, then collect performance evidence separately. Studio&#39;s <strong>Julia extension REPL</strong> action delegates to the Julia extension&#39;s own REPL, which keeps the environment selected in Julia&#39;s status bar; check it before running code. The dedicated PerfChecker terminal uses the selected controller project and remains a separate action.</p><h3 id="Julia-extension-compatibility" tabindex="-1">Julia extension compatibility <a class="header-anchor" href="#Julia-extension-compatibility" aria-label="Permalink to &quot;Julia extension compatibility {#Julia-extension-compatibility}&quot;">​</a></h3><p>Native editor qualification found a language-server startup failure with the official Julia extension <strong>1.174.2</strong> and Julia <strong>1.13.1</strong>: SymbolServer reports <code>KeyError: _apply</code>. This is a concrete failure of that language-server combination. PerfChecker&#39;s controller and measurement workers have separate executable and project checks.</p><p>The native Linux and Windows checks passed with VS Code <strong>1.141.0</strong>, Julia extension <strong>1.249.2</strong> and Julia <strong>1.12.7</strong>, including controller selection in a second workspace folder. The recorded build was VSIX <code>2e722b2d575a</code>, using Core 1.0.1 source tree <code>4fbc3c25543aa4f9b1154c227e5432f0cd62df91</code> before General registration. This result does not establish the same combination on other operating systems. The release report records each platform actually exercised. Configure <code>perfchecker.juliaExecutable</code> for the PerfChecker controller and <code>julia.executablePath</code> for the official Julia extension separately when those workflows need different runtimes. Select the real Julia binary in the corresponding folder settings, then inspect <code>VERSION</code> and <code>Base.active_project()</code> in that surface&#39;s terminal before executing code.</p><p>If you encounter the observed error, retain the version tuple and redacted Julia output, and consult the <a href="https://github.com/julia-vscode/julia-vscode/issues" target="_blank" rel="noreferrer">Julia extension issue tracker</a>.</p><h2 id="Tasks-and-runners" tabindex="-1">Tasks and runners <a class="header-anchor" href="#Tasks-and-runners" aria-label="Permalink to &quot;Tasks and runners {#Tasks-and-runners}&quot;">​</a></h2><p>Studio&#39;s tasks action opens VS Code&#39;s existing task runner. Opening Studio does not create <code>tasks.json</code>. Use established package tasks or the <a href="./../reference/cli">CLI</a> for a repeatable invocation.</p><p>Suite target environments, scenario workers, native TestItems, notebooks and debug sessions serve different purposes. Select their environments explicitly. A system profiler also needs its platform/provider dependencies; see <a href="./../native-profiling">native profiling</a> and <a href="./../reference/native-external">native dependencies</a>.</p><h2 id="Etendu-and-live-3D-companions" tabindex="-1">Etendu and live 3D companions <a class="header-anchor" href="#Etendu-and-live-3D-companions" aria-label="Permalink to &quot;Etendu and live 3D companions {#Etendu-and-live-3D-companions}&quot;">​</a></h2><p>PerfChecker&#39;s public companion commands accept an explicit folder URI:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Command</th><th style="text-align:right;">Contract</th></tr></thead><tbody><tr><td style="text-align:right;"><code>perfchecker.openStudioForWorkspace(uri)</code></td><td style="text-align:right;">Open Studio for an existing workspace folder</td></tr><tr><td style="text-align:right;"><code>perfchecker.openDesignerForWorkspace(uri)</code></td><td style="text-align:right;">Open the suite designer for that folder</td></tr><tr><td style="text-align:right;"><code>perfchecker.runLandscapeLiveForWorkspace(uri, quality)</code></td><td style="text-align:right;">Run the existing live-landscape measurement workflow</td></tr></tbody></table><p>These command IDs are available to Etendu/Beautiful Landscape and other extensions. The URI must identify the intended folder in VS Code. The companion owns rendering, scene lifetime and its quality setting; PerfChecker owns the configured measurement invocation and saved evidence.</p><h3 id="Measure-a-Beautiful-Landscape-scene" tabindex="-1">Measure a Beautiful Landscape scene <a class="header-anchor" href="#Measure-a-Beautiful-Landscape-scene" aria-label="Permalink to &quot;Measure a Beautiful Landscape scene {#Measure-a-Beautiful-Landscape-scene}&quot;">​</a></h3><ol><li><p>Open and trust the actual Beautiful Landscape game folder. Prepare its Julia rendering environment and download its required scene assets according to the companion&#39;s installation instructions. Its <code>EtenduGame.toml</code> must declare <code>id = &quot;etendu.beautifullandscape&quot;</code> and <code>entrypoint = &quot;scripts/play.jl&quot;</code>.</p></li><li><p>Check the folder&#39;s PerfChecker controller environment separately from the renderer environment. The cancellation fix belongs to the <strong>Core 1.0.1 candidate</strong>; use its corrected registered release once available. The public Core 1.0.0 provider can leave a rendering worker running after interruption.</p></li><li><p>In the companion, select this folder and a quality profile declared in <code>config/quality.toml</code>, such as <code>mobile-leger</code>. That file uses the <code>beautiful-landscape-quality/1</code> schema. The game must supply its actual <code>perf/live_provider.jl</code>; PerfChecker validates these files before execution.</p></li><li><p>Start the companion&#39;s live measurement action. It passes the explicit folder URI and quality slug to <code>perfchecker.runLandscapeLiveForWorkspace</code>. Both arguments are required; the palette entry alone cannot select them.</p></li><li><p>Read <strong>View → Output → PerfChecker Live</strong> while the progress notification is active. Use its cancellation control to interrupt the run, then wait for worker cleanup before starting another measurement or closing the scene.</p></li><li><p>After a successful run, PerfChecker opens the saved <code>manifest.json</code> under <code>perf/results/live/run-&lt;run-id&gt;/</code>. Retain the complete bundle, including its integrity document, observations and recorded environment.</p></li></ol><p>The current provider records <code>landscape.cpu.{median,p95,p99}</code> and <code>landscape.submit_interval.{median,p95,p99}</code> in milliseconds. Its submission boundary is <code>SDL_SubmitGPUCommandBuffer</code>. Read the saved warmup, measured submission count, scene digest, quality profile, effective resolution and device identity before comparing runs. The manifest explicitly records GPU timing and physical presentation as <code>unavailable</code>; these observations do not measure displayed frame rate.</p><p>Software qualification has exercised the real compiled provider bridge with the Landscape v0.1.0 scene, five SDK v0.1.1 modules, Mesa <strong>llvmpipe</strong> on a CPU, 40 submitted frames after warmup and six real observations in milliseconds. Two changing rendered scene buffers were observed before cancellation. The corrected candidate stopped all tracked owned processes before the test display closed, preserved an unrelated <code>.mem</code> file and published no completed evidence for the cancelled run.</p><p>This opt-in test passed against Core candidate <code>11011e1f8999</code>. The package source and tests are byte-identical in candidate <code>975d9351250a</code> (tree <code>7efea7f007cbdd78141fbebef63eeefcebc0f54e</code>); only the spelling configuration changed. Registration and the extension&#39;s final release qualification remain separate prerequisites for the public 1.0.1 workflow. The native VS Code companion button, hardware GPU timing and physical display presentation have not been qualified by this software test.</p><p>Before a live graphics comparison, keep the scene, quality, device and workload configuration comparable. Retain the resulting evidence and its configuration; a changed scene or quality profile requires a new, explicitly selected run.</p>`,44))])}const k=r(c,[["render",h]]);export{v as __pageData,k as default};
